// Prompt 2 parser + Supabase callback body builder
//
// Configure these Make Code inputs:
// rawInput            = Claude Prompt 2 text response
// jobId               = original webhook job_id
// providerExecutionId = Make execution ID (optional)
// inputTokens         = Prompt 2 input tokens (optional)
// outputTokens        = Prompt 2 output tokens (optional)

var value = input.rawInput;

// Unwrap common AI response formats.
if (typeof value === "object" && value !== null) {
    if (typeof value.text === "string") {
        value = value.text;
    } else if (typeof value.content === "string") {
        value = value.content;
    } else if (
        Array.isArray(value.content) &&
        value.content[0] &&
        typeof value.content[0].text === "string"
    ) {
        value = value.content[0].text;
    } else if (
        value.choices &&
        value.choices[0] &&
        value.choices[0].message &&
        typeof value.choices[0].message.content === "string"
    ) {
        value = value.choices[0].message.content;
    } else {
        value = JSON.stringify(value);
    }
}

var rawText = String(value || "").trim();

if (!rawText) {
    throw new Error("Claude Prompt 2 returned no text");
}

// Extract the scratchpad.
var scratchpad = null;
var scratchpadMatch = rawText.match(
    /<scratchpad>([\s\S]*?)<\/scratchpad>/i
);

if (scratchpadMatch) {
    scratchpad = scratchpadMatch[1].trim();
}

// Remove the scratchpad from the JSON candidate.
var text = rawText
    .replace(/<scratchpad>[\s\S]*?<\/scratchpad>/i, "")
    .trim();

// Remove Markdown code fences.
var fenceMatch = text.match(/```(?:json)?\s*([\s\S]*?)```/i);

if (fenceMatch) {
    text = fenceMatch[1].trim();
}

// Find the first complete JSON object using brace-depth matching.
var start = text.indexOf("{");

if (start === -1) {
    throw new Error(
        "Prompt 2 response did not contain a JSON object. Preview: " +
        text.slice(0, 300)
    );
}

var depth = 0;
var inString = false;
var escaped = false;
var jsonText = "";

for (var i = start; i < text.length; i++) {
    var character = text.charAt(i);

    if (escaped) {
        escaped = false;
        continue;
    }

    if (character === "\\" && inString) {
        escaped = true;
        continue;
    }

    if (character === '"') {
        inString = !inString;
        continue;
    }

    if (inString) continue;

    if (character === "{") {
        depth++;
    } else if (character === "}") {
        depth--;

        if (depth === 0) {
            jsonText = text.substring(start, i + 1);
            break;
        }
    }
}

if (!jsonText) {
    throw new Error("Prompt 2 returned an incomplete JSON object");
}

// Repair a few common model-output problems.
jsonText = jsonText
    .replace(/,(\s*[}\]])/g, "$1")
    .replace(/[\u201C\u201D]/g, '"')
    .replace(/[\u2018\u2019]/g, "'");

var extractedContent;

try {
    extractedContent = JSON.parse(jsonText);
} catch (error) {
    throw new Error(
        "Prompt 2 returned invalid JSON: " +
        error.message +
        ". Preview: " +
        jsonText.slice(0, 300)
    );
}

if (
    !extractedContent ||
    typeof extractedContent !== "object" ||
    Array.isArray(extractedContent)
) {
    throw new Error("Prompt 2 JSON must be an object");
}

var jobId = String(input.jobId || "").trim();

if (!jobId) {
    throw new Error("Missing original webhook jobId");
}

function safeInteger(value) {
    var number = Number(value || 0);

    return Number.isSafeInteger(number) && number >= 0
        ? number
        : 0;
}

var callbackPayload = {
    job_id: jobId,
    status: "completed",
    provider_execution_id: String(
        input.providerExecutionId || ""
    ).trim(),
    provider_execution_url: String(
        input.providerExecutionUrl || ""
    ).trim(),
    extracted_content: extractedContent,
    raw_extracted_text: rawText,
    scratchpad: scratchpad,
    input_tokens: safeInteger(input.inputTokens),
    output_tokens: safeInteger(input.outputTokens)
};

return {
    callbackBody: JSON.stringify(callbackPayload),
    json: JSON.stringify(extractedContent),
    scratchpad: scratchpad
};
